  // 2026-11-07：登录页面逐页检查（设置、自动化、自定义市场、安全及动态菜单）
  "New Automation": "新建自动化",
  "Bring Devin into your recurring and event-driven workflows": "让 Devin 参与定期执行和事件触发的工作流程",
  "Mine": "我的",
  "Let Devin find new ways to help": "让 Devin 寻找更多可以协助你的工作",
  "Devin looks at your recent work to find repetitive tasks worth automating.": "Devin 会查看你最近的工作，找出适合自动化的重复任务。",
  "Suggest automations for me": "为我推荐自动化",
  "Suggested automations": "推荐的自动化",
  "Monitoring & Triage": "监控与问题分流",
  "CI/CD & Release": "CI/CD 与发布",
  "Project Management": "项目管理",
  "Triage Bug Reports": "缺陷报告分流",
  "Watches a Slack channel for bug reports — when one comes in, Devin triages it, investigates the root cause, and replies in the thread with its findings.": "监控 Slack 频道中的缺陷报告；收到报告后，Devin 会分类处理、调查根本原因，并在消息串中回复调查结果。",
  "Triage Support Requests": "支持请求分流",
  "Watches your support channel — when a request comes in, Devin investigates the codebase and docs to draft an accurate reply in the thread and flags anything that needs escalation.": "监控支持频道；收到请求后，Devin 会检查代码和文档，在消息串中拟定准确的回复，并标记需要升级处理的问题。",
  "Investigate Alerts Triggered": "调查触发的告警",
  "When an alert lands in your Slack alerts channel, Devin uses the Datadog MCP to pull metrics, logs, and traces — then posts a root-cause analysis in the thread.": "Slack 告警频道收到告警后，Devin 会通过 Datadog MCP 获取指标、日志和追踪数据，并在消息串中发布根因分析。",
  "Fix Sentry Errors Daily": "每日修复 Sentry 错误",
  "Every morning, Devin pulls the top unresolved Sentry errors, investigates each one, and opens fix PRs — so your team reviews fixes instead of triaging errors.": "每天早晨，Devin 会获取最重要的未解决 Sentry 错误，逐一调查并创建修复 PR，让团队专注于审查修复。",
  "Daily Error Report": "每日错误报告",
  "Every morning, Devin scans Datadog for new and spiking errors across your services — then posts a concise error report to Slack.": "每天早晨，Devin 会扫描 Datadog 中各服务新增和激增的错误，并向 Slack 发布简明的错误报告。",
  "Recurring Capacity Planning": "定期容量规划",
  "On a schedule, Devin reviews usage and resource-utilization trends to forecast capacity needs — flagging services approaching their limits and recommending where to scale.": "Devin 会定期分析用量和资源利用趋势，预测容量需求，标记接近上限的服务并提出扩容建议。",
  "Fix CI Failures": "修复 CI 失败",
  "/devin Issue Fix": "/devin 问题修复",
  "Weekly Dependency Update": "每周依赖更新",
  "Every Monday, Devin scans for outdated packages, reviews changelogs for breaking changes, and opens update PRs — grouped by risk level.": "每周一，Devin 会扫描过时的软件包，检查变更日志中的破坏性变更，并按风险等级分组创建更新 PR。",
  "Weekly Changelog": "每周变更日志",
  "Every Friday, Devin compiles merged PRs into a categorized changelog and opens a PR to update CHANGELOG.md.": "每周五，Devin 会将已合并的 PR 整理为分类变更日志，并创建 PR 更新 CHANGELOG.md。",
  "Stale PR Cleanup": "清理长期未更新的 PR",
  "A weekly scan for pull requests that haven't been updated in over a week. Devin checks for merge conflicts and posts a friendly nudge on each one.": "每周扫描超过一周未更新的 PR。Devin 会检查合并冲突，并在每个 PR 中发布友善的提醒。",
  "Catch bugs in merged PRs": "查找已合并 PR 中的缺陷",
  "Reviews every push to your main branch. When Devin is sure it found a real bug, it messages the person who merged the change and offers to fix it.": "审查主分支上的每次推送。Devin 确认发现缺陷后，会联系合并该变更的人员并提出修复建议。",
  "Catch dead code in merged PRs": "查找已合并 PR 中的无用代码",
  "Reviews every push to your main branch. When Devin is sure the change left dead code behind, it messages the person who merged it and offers to remove it.": "审查主分支上的每次推送。Devin 确认变更遗留了无用代码后，会联系合并人员并提出清理建议。",
  "Dependency Vulnerability Scanner": "依赖漏洞扫描",
  "Daily scan for known CVEs in your dependencies. Devin checks advisory databases, prioritizes by severity, and opens fix PRs.": "每日扫描依赖中的已知 CVE 漏洞。Devin 会检查安全通告数据库，按严重程度排序并创建修复 PR。",
  "Secret Scanner": "密钥泄露扫描",
  "Daily scan for leaked credentials, API keys, and tokens in your codebase. Devin replaces hardcoded secrets with environment variable references and opens fix PRs.": "每日扫描代码中泄露的凭证、API 密钥和令牌。Devin 会将硬编码密钥替换为环境变量引用，并创建修复 PR。",
  "Code Pattern Enforcer": "代码规范检查",
  "Weekly comparison of your repo against a golden reference repository to identify deviations from established patterns and open alignment PRs.": "每周将你的仓库与标准参考仓库比较，找出偏离既定规范的地方，并创建统一规范的 PR。",
  "OWASP Security Hardening": "OWASP 安全加固",
  "Weekly scan for OWASP Top 10 vulnerabilities: injection flaws, XSS, missing auth checks, and insecure defaults — with fix PRs.": "每周扫描 OWASP 十大安全漏洞，包括注入、XSS、缺失的身份验证检查及不安全的默认配置，并创建修复 PR。",
  "Cloudflare Security Audit": "Cloudflare 安全审计",
  "Weekly review of Cloudflare audit logs to flag suspicious activity, configuration changes, and potential security issues.": "每周审查 Cloudflare 审计日志，标记可疑活动、配置变更和潜在安全问题。",
  "Weekly Status Digest": "每周进展摘要",
  "Every Monday, Devin compiles the past week's merged PRs into a concise status update and posts it to Notion.": "每周一，Devin 会将上周合并的 PR 整理为简明进展摘要，并发布到 Notion。",
  "Sprint Progress Report": "迭代进度报告",
  "A daily standup summary from Asana: Devin pulls task status across projects and posts a progress update to Slack.": "根据 Asana 生成每日站会摘要：Devin 获取各项目的任务状态，并向 Slack 发布进度更新。",
  "Backlog Cleanup": "清理积压任务",
  "A weekly pass over your Linear backlog: Devin closes stale and duplicate issues, flags untriaged ones, and fills in missing labels, priorities, and estimates.": "每周整理 Linear 积压任务：Devin 关闭过时或重复的问题，标记尚未分流的问题，并补齐标签、优先级和工作量估算。",
