  "Choose how Devin reviews pull requests, what it approves, and how reviews are billed.": "设置 Devin 如何审查 PR、批准哪些变更以及如何计费。",
  "Custom reviewers": "自定义审查器",
  "Autoapprover": "自动批准",
  "Autoapprover is for repositories that require an approving review before merging. It approves the enrolled pull requests that are safe to merge without a person, so reviewers only see the rest. Its approval counts as one approving review from Devin, not as a code owner review, and it never merges on its own.": "自动批准功能适用于合并前必须获得审查批准的仓库。它会批准已纳入规则且无需人工干预即可安全合并的 PR，其余 PR 交由审查者处理。它的批准仅计为 Devin 的一次批准，不属于代码所有者审查，也不会自行合并 PR。",
  "Autoapprover rules": "自动批准规则",
  "Choose which pull requests Autoapprover evaluates. It runs on every push.": "选择自动批准功能评估的 PR。每次推送后都会执行评估。",
  "No Autoapprover rules yet": "尚无自动批准规则",
  "Rules choose which pull requests Autoapprover evaluates and approves on your behalf.": "规则决定自动批准功能代表你评估和批准哪些 PR。",
  "Tell Autoapprover what your team approves without review and what always needs a human.": "告诉自动批准功能：团队允许哪些变更免于人工审查，哪些始终需要人工审核。",
