  "What your team can do with Devin without leaving Teams": "团队无需离开 Teams 即可让 Devin 完成的工作",
  "A bug shows up in the chat": "聊天中出现缺陷报告",
  "It gets fixed in the same chat where it's being discussed.": "在讨论问题的同一个聊天中完成修复。",
  "The afternoon alert": "下午收到的告警",
  "Whoever opens the alert already has a diagnosis.": "打开告警时，诊断结果已经准备好。",
  "A new teammate's question": "新同事提出的问题",
  "The help channel answers without waiting for the one person who knows.": "帮助频道直接给出答案，无需等待熟悉情况的人回复。",
  "A second look before merging": "合并前再检查一次",
  "It reviews the PR while the team keeps working.": "团队继续工作时，Devin 同时审查 PR。",
  "Starting from the spec": "从需求文档开始",
  "It picks up the spec the team already wrote in SharePoint.": "直接使用团队在 SharePoint 中编写的需求文档。",
  "Checkout team": "结账团队",
  "Group chat": "群聊",
  "You": "你",
  "AI generated": "AI 生成",
  "Checkout fails when a coupon is bigger than the cart total. Support just sent it over.": "优惠券金额超过购物车总额时，结账会失败。支持团队刚转来了这个问题。",
  "can you take a look?": "能帮忙看看吗？",
  "Reproduced it: the discount was applied after tax, so the total went negative. Fix and test in": "已复现：折扣在税费计算后应用，导致总额变为负数。修复和测试见",
  "what about 100% coupons?": "100% 折扣的优惠券呢？",
  "Covered: I added that case to the same PR.": "已覆盖：我在同一个 PR 中添加了这个用例。",
  "Devin reads the conversation as context, and every reply continues the same session.": "Devin 会将对话作为上下文，每次回复都延续同一个会话。",
  "Payments › Alerts": "支付 › 告警",
  "Channel": "频道",
  "Alerts": "告警",
  "payments-api: p95 above 2 s for the last 10 minutes.": "payments-api：过去 10 分钟内，p95 延迟超过 2 秒。",
  "Likely cause: the 14:02 deploy added an unindexed query (": "可能原因：14:02 的部署新增了一个未建立索引的查询（",
  "). Options: roll back, or merge the index in": "）。可选操作：回滚，或合并以下 PR 中的索引：",
  ". I haven't changed anything.": "。我尚未进行任何更改。",
  "Rolling back, thanks.": "正在回滚，谢谢。",
  "Nobody mentioned Devin: an automation with a Microsoft Teams trigger watches the channel. Set it up in Automations.": "无需提及 Devin：带有 Microsoft Teams 触发条件的自动化会监控频道。可在自动化页面中设置。",
  "Platform › Help": "平台 › 帮助",
  "I just joined the team. Where is the public API rate limit configured?": "我刚加入团队。公共 API 的频率限制在哪里配置？",
  "In": "位于",
  ", per plan. Enterprise customers override it in": "，按订阅方案配置。企业客户可在以下位置覆盖设置：",
  ". To try it locally:": "。要在本地尝试，请执行：",
  "Perfect, thanks!": "太好了，谢谢！",
  "Each thread is one session: follow-up questions in the thread keep all the context.": "每个消息串对应一个会话：在同一消息串中继续提问会保留全部上下文。",
  "Billing team": "计费团队",
  "I want to merge": "我想合并",
  "today, it touches the tax calculation.": "，计划今天完成，它涉及税费计算。",
  "can you give it a look?": "能帮忙审查一下吗？",
  "Two things before merging: rounding changes for amounts with three decimals, and the foreign-currency invoice case is missing. I left the comments on the PR.": "合并前有两点需要处理：三位小数金额的舍入行为发生了变化，并且缺少外币发票用例。我已在 PR 中留下评论。",
  "Great, fixing it.": "好的，正在修复。",
  "Devin works on the repositories your organization connected, with the same access as in the web app.": "Devin 使用组织已连接的仓库，访问权限与网页应用一致。",
  "Reporting team": "报表团队",
  "I put the spec for the new export in SharePoint.": "我已把新版导出功能的需求文档放到 SharePoint。",
  "can you start with the CSV part?": "能先实现 CSV 部分吗？",
  "I read": "我已阅读",
  ". The CSV export is in": "。CSV 导出实现见",
  ". One question for XLSX: is there a row limit? The spec doesn't say.": "。关于 XLSX 有个问题：是否限制行数？需求文档中没有说明。",
  "Uses the Microsoft 365 MCPs: each person connects their own account, and Devin suggests installing them when it needs them.": "使用 Microsoft 365 MCP 服务：每个人连接自己的账户，Devin 会在需要时建议安装。",
  "APP": "应用",
  "Triaged and fixed the auth issues in": "已分类处理并修复身份验证问题，见",
  "aside wait, why did we zorple the jorp here?": "aside 等等，为什么这里要这样处理？",
  "Looks great as is": "目前这样很好",
  "Thanks, Oliver!": "谢谢你，Oliver！",
  "I think the jorp was already zorpled in the last deploy": "我想上次部署已经处理过这个问题了",
  "I'll start refactoring the auth module now.": "我现在开始重构身份验证模块。",
  "!ask how auth in website works?": "!ask 网站的身份验证是如何工作的？",
  "Authentication is handled via JWT tokens stored in localstorage.": "身份验证通过存储在 localstorage 中的 JWT 令牌处理。",

  // 2026-11-07：登录页面逐页检查（设置、自动化、自定义市场、安全及动态菜单）
  "Create manually": "手动创建",
